import { applyColumnOrder } from 'vue-shapeshifter-table'
// Persist keys only, after the user chooses to save:
localStorage.setItem('table-order', JSON.stringify(headers.value.map(h => h.key)))
// Restore after fetching the matching dataset:
const order = JSON.parse(localStorage.getItem('table-order') ?? 'null')
const restored = applyColumnOrder(headers.value, rows.value, order)
headers.value = restored.headers
rows.value = restored.rows

function onCellUpdate(event) {
  // rowIndex is the absolute source row, even with pagination.
  console.log(event.rowIndex, event.columnIndex, event.value)
